      D.MON_SKILL[m.k] = m.sk;
      D.MON_TAG_OF[m.k] = m.tag;
      D.MON_RACE_OF[m.k] = m.race;
      D.CODEX.push({ id:m.k, cat:'monster', n:m.n, e:m.e, img:'', where:m.zone + '(野外)', d:m.cx + '(怕:' + D.defTool(m.tool).e + D.defTool(m.tool).n + ')' });
